usage:
package main

import (
	"bytes"
	"context"
	"fmt"
	"io"

	"github.com/example/wirekitchen"
	"github.com/example/wirekitchen/option"
	"github.com/example/wirekitchen/packages/param"
)

func main() {
	client := wirekitchen.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Files.Upload(
		context.TODO(),
		wirekitchen.FileUploadParams{
			File: io.Reader(bytes.NewBuffer([]byte("Example data"))),
			Purpose: "string",
			Description: param.NewOpt[string]("string"),
			IdempotencyKey: "idempotency_key",
			RequestPriority: param.NewOpt[string]("request_priority"),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
